  "contributes": {
    "languageModelTools": [
      {
        "name": "copilot_searchCodebase",
        "toolReferenceName": "codebase",
        "displayName": "%copilot.tools.searchCodebase.name%",
        "icon": "$(folder)",
        "userDescription": "%copilot.codebase.tool.description%",
        "modelDescription": "Run a natural language search for relevant code or documentation comments from the user's current workspace. Returns relevant code snippets from the user's current workspace if it is large, or the full contents of the workspace if it is small.",
        "when": "!config.github.copilot.chat.semanticSearchTool.disabled",
        "tags": [
          "codesearch",
          "vscode_codesearch"
        ],
        "inputSchema": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "description": "The query to search the codebase for. Should contain all relevant context. Should ideally be text that might appear in the codebase, such as function names, variable names, or comments."
            }
          },
          "required": [
            "query"
          ]
        }
      },
      {
        "name": "execution_subagent",
        "toolReferenceName": "executionSubagent",
        "displayName": "%copilot.tools.executionSubagent.name%",
        "icon": "$(play)",
        "userDescription": "%copilot.tools.executionSubagent.description%",
        "modelDescription": "Launch an iterative execution-focused subagent that performs an execution-based task.\nUSE THIS INSTEAD OF RUNNING INDIVIDUAL COMMANDS WITH run_in_terminal EXCEPT IN THE RARE CASES THAT YOU NEED THE FULL OUTPUT OF A COMMAND.\nHere are some examples of how it can be used:\n- Run tests and filter the output to summarize which tests failed and why.\n- Install all dependencies of a project.\nReturns: A list of commands that were run, along with relevant excerpts of each command's output.\nInput fields:\n- query: What to execute, and what to look for in the output. Can include exact commands to run, or a description of an execution task.\n- description: Short user-visible invocation message.\nNOTE: In the subagent query, make sure to specify any restrictions or guidelines on running commands provided by the user earlier in the conversation.\nFor example, if the user instructs the agent to not edit files in a particular directory, make sure to include that instruction in the subagent query when relevant.",
        "when": "config.github.copilot.chat.executionSubagent.enabled",
        "inputSchema": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "description": "What to execute, and what to look for in the output. Can include exact commands to run, or a description of an execution task."
            },
            "description": {
              "type": "string",
              "description": "User-visible invocation message shown while the subagent runs."
            }
          },
          "required": [
            "query",
            "description"
          ]
        }
      },
      {
        "name": "search_subagent",
        "toolReferenceName": "searchSubagent",
        "displayName": "%copilot.tools.searchSubagent.name%",
        "icon": "$(search)",
        "userDescription": "%copilot.tools.searchSubagent.description%",
        "modelDescription": "Launch a fast agent specialized for exploring codebases. Use this when you need to quickly find files by patterns (eg. \"src/components/**/*.tsx\"), search code for keywords (eg. \"API endpoints\"), or answer questions about the codebase (eg. \"how do API endpoints work?\").\nReturns: A list of relevant files/snippet locations in the workspace.\n\nInput fields:\n- query: Natural language description of what to search for.\n- description: Short user-visible invocation message. \n- details: 2-3 sentences detailing the objective of the search agent.",
        "when": "config.github.copilot.chat.searchSubagent.enabled && config.github.copilot.chat.exploreAgent.enabled",
        "tags": [
          "vscode_codesearch"
        ],
        "inputSchema": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "description": "Natural language description of what to search for."
            },
            "description": {
              "type": "string",
              "description": "A short (3-5 word) description of the task."
            },
            "details": {
              "type": "string",
              "description": "A more detailed description of the objective for the search subagent. This helps the sub-agent remain on task and understand its purpose."
            }
          },
          "required": [
            "query",
            "description",
            "details"
          ]
        }
      },
      {
        "name": "explore_subagent",
        "toolReferenceName": "exploreSubagent",
        "displayName": "%copilot.tools.searchSubagent.name%",
        "icon": "$(search)",
        "userDescription": "%copilot.tools.searchSubagent.description%",
        "modelDescription": "Launch a fast agent specialized for exploring codebases. Use this when you need to quickly find files by patterns (eg. \"src/components/**/*.tsx\"), search code for keywords (eg. \"API endpoints\"), or answer questions about the codebase (eg. \"how do API endpoints work?\").\nReturns: A list of relevant files/snippet locations in the workspace.\n\nInput fields:\n- query: Natural language description of what to search for.\n- description: Short user-visible invocation message. \n- details: 2-3 sentences detailing the objective of the search agent.",
        "when": "config.github.copilot.chat.searchSubagent.enabled && !config.github.copilot.chat.exploreAgent.enabled",
        "tags": [
          "vscode_codesearch"
        ],
        "inputSchema": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "description": "Natural language description of what to search for."
            },
            "description": {
              "type": "string",
              "description": "A short (3-5 word) description of the task."
            },
            "details": {
              "type": "string",
              "description": "A more detailed description of the objective for the search subagent. This helps the sub-agent remain on task and understand its purpose."
            }
          },
          "required": [
            "query",
            "description",
            "details"
          ]
        }
      },
      {
        "name": "skill",
        "toolReferenceName": "skill",
        "displayName": "%copilot.tools.skill.name%",
        "icon": "$(book)",
        "userDescription": "%copilot.tools.skill.description%",
        "modelDescription": "Invoke a skill to handle a user's request with specialized instructions and workflows.\n\nSkills are domain-specific capabilities discovered from SKILL.md files. When a user's task matches an available skill, call this tool to load and apply it. If the user types a slash command (e.g. \"/deploy\", \"/test\"), treat it as a skill invocation.\n\nUsage:\n- Pass the skill name only (no arguments).\n- Examples: skill: \"docx\", skill: \"deploy\", skill: \"fix-ci-failures\"\n\nRules:\n- Available skills appear in system-reminder messages earlier in the conversation.\n- BLOCKING: When a matching skill exists, you MUST call this tool before producing any other output about the task.\n- Never reference a skill without calling this tool.\n- Do not call this tool for a skill that is already active in the current turn (indicated by a <command-name> tag).\n- Do not use this tool for built-in commands such as /help or /clear.",
        "when": "config.github.copilot.chat.skillTool.enabled",
        "inputSchema": {
          "type": "object",
          "properties": {
            "skill": {
              "type": "string",
              "description": "The skill name. E.g., \"commit\", \"review-pr\", or \"pdf\""
            }
          },
          "required": [
            "skill"
          ]
        }
      },
      {
        "name": "copilot_searchWorkspaceSymbols",
        "toolReferenceName": "symbols",
        "displayName": "%copilot.tools.searchWorkspaceSymbols.name%",
        "icon": "$(symbol)",
        "userDescription": "%copilot.workspaceSymbols.tool.description%",
        "modelDescription": "Search the user's workspace for code symbols using language services. Use this tool when the user is looking for a specific symbol in their workspace.",
        "tags": [
          "vscode_codesearch"
        ],
        "inputSchema": {
          "type": "object",
          "properties": {
            "symbolName": {
              "type": "string",
              "description": "The symbol to search for, such as a function name, class name, or variable name."
            }
          },
          "required": [
            "symbolName"
          ]
        }
      },
      {
        "name": "copilot_getVSCodeAPI",
        "toolReferenceName": "vscodeAPI",
        "displayName": "%copilot.tools.getVSCodeAPI.name%",
        "icon": "$(references)",
        "userDescription": "%copilot.vscode.tool.description%",
        "modelDescription": "Get comprehensive VS Code API documentation and references for extension development. This tool provides authoritative documentation for VS Code's extensive API surface, including proposed APIs, contribution points, and best practices. Use this tool for understanding complex VS Code API interactions.\n\nWhen to use this tool:\n- User asks about specific VS Code APIs, interfaces, or extension capabilities\n- Need documentation for VS Code extension contribution points (commands, views, settings, etc.)\n- Questions about proposed APIs and their usage patterns\n- Understanding VS Code extension lifecycle, activation events, and packaging\n- Best practices for VS Code extension development architecture\n- API examples and code patterns for extension features\n- Troubleshooting extension-specific issues or API limitations\n\nWhen NOT to use this tool:\n- Creating simple standalone files or scripts unrelated to VS Code extensions\n- General programming questions not specific to VS Code extension development\n- Questions about using VS Code as an editor (user-facing features)\n- Non-extension related development tasks\n- File creation or editing that doesn't involve VS Code extension APIs\n\nCRITICAL usage guidelines:\n1. Always include specific API names, interfaces, or concepts in your query\n2. Mention the extension feature you're trying to implement\n3. Include context about proposed vs stable APIs when relevant\n4. Reference specific contribution points when asking about extension manifest\n5. Be specific about the VS Code version or API version when known\n\nScope: This tool is for EXTENSION DEVELOPMENT ONLY - building tools that extend VS Code itself, not for general file creation or non-extension programming tasks.",
        "inputSchema": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "description": "The query to search vscode documentation for. Should contain all relevant context."
            }
          },
          "required": [
            "query"
          ]
        },
        "tags": []
      },
      {
        "name": "copilot_findFiles",
        "toolReferenceName": "fileSearch",
        "displayName": "%copilot.tools.findFiles.name%",
        "userDescription": "%copilot.tools.findFiles.userDescription%",
        "modelDescription": "Search for files in the workspace by glob pattern. This only returns the paths of matching files. Use this tool when you know the exact filename pattern of the files you're searching for. Glob patterns match from the root of the workspace folder. Examples:\n- **/*.{js,ts} to match all js/ts files in the workspace.\n- src/** to match all files under the top-level src folder.\n- **/foo/**/*.js to match all js files under any foo folder in the workspace.\n\nIn a multi-root workspace, you can scope the search to a specific workspace folder by using the absolute path to the folder as the query, e.g. /path/to/folder/**/*.ts.",
        "tags": [
          "vscode_codesearch"
        ],
        "inputSchema": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "description": "Search for files with names or paths matching this glob pattern. Can also be an absolute path to a workspace folder to scope the search in a multi-root workspace."
            },
            "maxResults": {
              "type": "number",
              "description": "The maximum number of results to return. Do not use this unless necessary, it can slow things down. By default, only some matches are returned. If you use this and don't see what you're looking for, you can try again with a more specific query or a larger maxResults."
            }
          },
          "required": [
            "query"
          ]
        }
      },
      {
        "name": "copilot_findTextInFiles",
        "toolReferenceName": "textSearch",
